#!/bin/bash
set -e
echo "=== 慧根堂 Vite Build 产物还原 v2 ==="
CONTAINER="hgt-commercial-app-1"
BUILD_DIR="/var/www/public/build"

# 1. 创建目录
echo "[1/4] 创建目录..."
sudo docker exec $CONTAINER mkdir -p $BUILD_DIR/assets

# 2. 写入 manifest.json
echo "[2/4] 写入 manifest.json..."
sudo docker exec $CONTAINER sh -c 'echo "{\"resources/css/app.css\":{\"file\":\"assets/app-DdKH6GIn.css\",\"src\":\"resources/css/app.css\",\"isEntry\":true},\"resources/js/app.js\":{\"file\":\"assets/app-DUr89oQr.js\",\"name\":\"app\",\"src\":\"resources/js/app.js\",\"isEntry\":true}}" > '"$BUILD_DIR"'/manifest.json'

# 3. 写入 CSS (base64 decode)
echo "[3/4] 写入 app-DdKH6GIn.css (238KB)..."
sudo docker exec $CONTAINER sh -c "echo  | base64 -d > /assets/app-DdKH6GIn.css"

# 4. 写入 JS (base64 decode)
echo "[4/4] 写入 app-DUr89oQr.js (48KB)..."
sudo docker exec $CONTAINER sh -c "echo  | base64 -d > /assets/app-DUr89oQr.js"

# 验证
echo ""
echo "=== 验证 ==="
sudo docker exec $CONTAINER ls -la $BUILD_DIR/
sudo docker exec $CONTAINER ls -la $BUILD_DIR/assets/
echo ""
echo "✅ build 产物还原完成！访问 http://124.222.33.233:8080/login 验证"
